mapper.select:
SELECT h.user_search_history_id, CASE WHEN h.target_tag_id IS NOT NULL THEN 'TAG' ELSE 'USER' END AS historyType, h.target_user_no, u.nickname, ( SELECT rp.profile_file_id FROM ultary_pet rp WHERE rp.user_no = u.user_no AND rp.is_deleted = 0 AND rp.profile_file_id IS NOT NULL ORDER BY rp.priority ASC, rp.pet_id ASC LIMIT 1 ) AS profileFileId, h.target_tag_id, t.hashtag, , h.searched_at
AND ( h.searched_at < #{cursorSearchedAt} OR ( h.searched_at = #{cursorSearchedAt} AND h.user_search_history_id < #{cursorHistoryId} ) )
ORDER BY h.searched_at DESC, h.user_search_history_id DESC LIMIT #{limit}

mapper.delete:
DELETE FROM ultary_user_search_history
WHERE user_no = #{userNo}
  AND user_search_history_id = #{userSearchHistoryId}
